var t=`0723-mufete`;var n=`world-0723`;var a=`AO`;var r=`central-africa`;var o=4;var s=82;var l={en:`Mufete`,ua:`Муфете`};var g={en:`Mufete is a Angola classic prepared with tilapia, lemon juice, garlic, sweet potato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Муфете, страва кухні країни Ангола зі складниками: тилапія, лимонний сік, часник, батат. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 30 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 30 хвилин.`,t:[`marinating`],m:30,i:[[`tilapia`,900,`g`],[`lemon-juice`,50,`ml`],[`garlic`,4,`clove`],[`hot-paprika`,5,`g`]]},{en:`Grill over medium-high heat for about 23 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 23 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:23,i:[[`extra-virgin-olive-oil`,50,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 25 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 25 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:25,i:[[`sweet-potato`,600,`g`],[`water`,900,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`yellow-onion`,180,`g`],[`tomato`,240,`g`],[`parsley`,16,`g`]]}];var m={slug:t,id:n,country:`AO`,region:r,servings:4,minutes:82,title:l,text:g,steps:u};export{a as country,m as default,n as id,s as minutes,r as region,o as servings,t as slug,u as steps,g as text,l as title};